{
  "claims": [
    {
      "claim": "Record 1-4 explicitly includes cefadroxil (the query molecule) among oral cephalosporins with absolute bioavailability greater than 90% in humans; cephradine, a close structural analogue, had measured human oral bioavailability of 85-94% and near-complete absorption.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1"],
      "record_ids": ["Record 1-1", "Record 1-2", "Record 1-3", "Record 1-4", "Record 1-5"]
    },
    {
      "claim": "Amoxicillin, sharing the same 4-hydroxyphenylglycyl side chain as the query, has absolute human oral bioavailability of about 70-93% in healthy/fasted adults and 55-59% in frail elderly or paediatric populations; all reported means are above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 3", "Molecule 4"],
      "record_ids": ["Record 3-1", "Record 3-2", "Record 3-3", "Record 4-1", "Record 4-2", "Record 4-3", "Record 4-4", "Record 4-5", "Record 4-6", "Record 4-7", "Record 4-8", "Record 4-9", "Record 4-10"]
    },
    {
      "claim": "Cefroxadine and cephradine, oral aminocephalosporins similar to the query, show essentially complete oral bioavailability in humans, supporting the high-absorption potential of this beta-lactam class.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 5", "Molecule 6"],
      "record_ids": ["Record 5-1", "Record 6-1"]
    },
    {
      "claim": "Cephalexin, the direct des-hydroxy analogue of the query, is a PEPT1 substrate; human data show high jejunal permeability, a fraction absorbed near 0.90, and extremely good enteral absorption despite low passive permeability, supporting carrier-mediated oral absorption for the query.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 11"],
      "record_ids": ["Record 11-15", "Record 11-17", "Record 11-18", "Record 11-27", "Record 11-28", "Record 11-29", "Record 11-36", "Record 11-46"]
    },
    {
      "claim": "PepT1 transports cephalexin-type beta-lactams stereoselectively, and the query's L-4-hydroxyphenylglycyl configuration matches the preferred substrate form, supporting intestinal carrier-mediated uptake.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 13"],
      "record_ids": ["Record 13-1"]
    },
    {
      "claim": "Under fed conditions, the closely related 4-hydroxyphenylglycyl-cephem cefprozil showed substantial oral AUC after a single dose, indicating that this scaffold remains orally absorbed in the fed state, though this record does not quantify F.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 12"],
      "record_ids": ["Record 12-1"]
    },
    {
      "claim": "Ampicillin, a structurally related oral beta-lactam with generally lower absorption, still has human oral bioavailability values of 29-62%, all above the 20% threshold, providing a conservative lower-bound analogy.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 9", "Molecule 10"],
      "record_ids": ["Record 9-1", "Record 10-1", "Record 10-2", "Record 10-3", "Record 10-4", "Record 10-5", "Record 10-6", "Record 10-7", "Record 10-8", "Record 10-9", "Record 10-10"]
    },
    {
      "claim": "A more distant cephalosporin record reports about 40% human oral bioavailability, also above the threshold, although this structure is less transferable to the query.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 8"],
      "record_ids": ["Record 8-1"]
    },
    {
      "claim": "Low oral F values for cefazolin (1.5-2%), oral ceftriaxone (8%), cephalexin in horses (~5%), and one isolated human cephalexin control value (14.2%) come from non-analogous injectable cephalosporins, another species, or poorly transferable/confounded settings; they are directional but weak evidence for F below 20%.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 2", "Molecule 7", "Molecule 11"],
      "record_ids": ["Record 2-1", "Record 7-1", "Record 11-2", "Record 11-5", "Record 11-7"]
    },
    {
      "claim": "A high-protein diet can reduce cephalexin/cefadroxil absorption in an in-situ perfusion system, but this does not establish a fed-state absolute F below 20% and is outweighed by the broader human oral-absorption evidence for this class.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 11"],
      "record_ids": ["Record 11-16"]
    }
  ],
  "final_prediction": "pass"
}
